+			return dissect_netlink_attributes_to_end(tvb, hf_nft_rule_attr, ett_nft_rule_attr, info, nl_data, tree, offset, dissect_nft_rule_attrs);
+
+		default:
+			/* Other nftables message types not yet implemented */
+			return offset;
+	}
